//! Utility for detecting insecure configuration options. Port of
//! `org.apache.camel.util.SecurityUtils`.
//!
//! The security options table is generated by the Camel build tooling from the
//! `security = "..."` metadata of component, data format and language options.
//!
//! *Since Camel 4.19*

use crate::security_violation::SecurityViolation;
use crate::value::Value;
use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

/// Category for options that weaken TLS (such as trusting all certificates).
pub const INSECURE_SSL: &str = "insecure:ssl";
/// Category for options that enable (Java) deserialization of untrusted data.
pub const INSECURE_SERIALIZATION: &str = "insecure:serialization";
/// Category for options only meant for development.
pub const INSECURE_DEV: &str = "insecure:dev";

/// Information about a security-sensitive configuration option.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct SecurityOption {
    /// The security category (e.g., `insecure:ssl`, `insecure:serialization`, `insecure:dev`).
    pub category: &'static str,
    /// The value that makes this option insecure (e.g., `true` for boolean flags).
    pub insecure_value: &'static str,
}

